from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[2]
def build(token):
 assets=ROOT/'software/android_nav/assets';html=(assets/'index.html').read_text('utf-8-sig');css=(assets/'style.css').read_text('utf-8-sig');js=(assets/'app.js').read_text('utf-8-sig')
 html=re.sub(r'<meta http-equiv="Content-Security-Policy"[^>]*>','',html)
 js=js.replace('function drawDevice(){','function drawDeviceIllustration(){',1)
 js=js.replace("if(page==='nav'){ctx.save()", "if(page==='nav'&&state.fresh){ctx.save()")
 js=js.replace("function openSearch(){$('searchModal').hidden=false;setTimeout(()=>$('destination').focus(),100)}", "function openSearch(){showPage('plan');notify('电脑联调使用公开 DEMO 路线，请点击开始导航；真实目的地在安卓应用测试')}")
 js=js.replace("case'simulate':drawDevice();notify('这是设备显示示意预览；同步后用于真实导航');break;", "case'simulate':drawDevice();notify('当前预览来自已同步数据，使用与开发板相同的渲染代码');break;")
 js+='''\nfunction drawDevice(){for(const id of ['devicePreview','appearancePreview']){const canvas=$(id),ctx=canvas.getContext('2d');ctx.clearRect(0,0,480,320);if(window.PcFrame)ctx.drawImage(window.PcFrame,0,0,480,320);else{ctx.fillStyle='#091014';ctx.fillRect(0,0,480,320);ctx.fillStyle='#93c5fd';ctx.font='18px system-ui';ctx.fillText('请连接导航屏，加载同步画面',80,155);}}}\n'''
 panel='''<aside id="pcPanel"><div class="pcHeading"><span class="pcDot" id="pcDot"></span><h1>电脑与导航屏联调</h1><span class="pcTag">DEMO</span></div><p class="pcIntro">公开济南路线与真实路网 · 电脑模拟导航位置<br>车辆位置独立读取 ATGM336H，不使用模拟位置替代</p><div class="pcActions"><button data-pc="connect">连接导航屏</button><button data-pc="begin">开始同步导航</button><button data-pc="pause">暂停 / 继续</button><button data-pc="step">前进 100 米</button><button data-pc="stale">模拟定位失效</button><button data-pc="fresh">恢复定位</button><button data-pc="reset">回到起点</button><button data-pc="end">结束导航</button><button data-pc="disconnect">断开电脑连接</button></div><label class="pcSpeed">模拟速度 <input id="pcSpeed" type="range" min="0" max="60" value="24"><strong id="pcSpeedLabel">24 km/h</strong></label><p id="pcStatus">请先连接导航屏</p><div class="pcScreen"><img id="pcFrame" alt="开发板同源渲染同步预览"><div id="pcNoFrame">连接后显示同步画面</div></div><small class="pcExplain">采用固件的同一份 PhoneRenderer 代码，根据已发送数据渲染；不是屏幕截屏。配色通过设备读回校验，导航接收通过串口核对。</small><div class="pcFacts"><div><span>链路</span><b id="pcLink">未连接</b></div><div><span>导航快照</span><b id="pcTx">0</b></div><div><span>提交确认</span><b id="pcAck">0</b></div><div><span>屏幕路网</span><b id="pcRoads">—</b></div><div><span>配色回读</span><b id="pcSettings">未同步</b></div><div><span>屏幕实测刷新率</span><b id="pcFPS">—</b></div><div><span>串口 Ready</span><b id="pcReady">—</b></div><div><span>串口速度</span><b id="pcBoardSpeed">—</b></div><div><span>串口路线 / 路网</span><b id="pcBoardMap">—</b></div></div><pre id="pcErrors">等待电脑连接</pre><p class="pcHelp">电脑联调期间，保持手机应用会话关闭。重新启动本地服务后，请刷新此页面；HTML 单独打开也可连接正在运行的服务。</p></aside>'''
 extra='''body.pcMode{display:flex;justify-content:center;align-items:flex-start;gap:25px;padding:24px;flex-wrap:wrap}body.pcMode #app{width:390px;height:844px;max-height:none;flex-shrink:0;border:8px solid #252b28;border-radius:39px;box-shadow:0 14px 40px #21362925}#pcPanel{width:470px;max-width:calc(100vw - 36px);background:#fffefa;border:1px solid #e4e6df;border-radius:24px;padding:24px;box-shadow:0 12px 30px #313c2210}.pcHeading{display:flex;align-items:center;gap:10px}.pcHeading h1{font-size:21px}.pcDot{width:9px;height:9px;border-radius:50%;background:#999}.pcDot.ready{background:#20b45d}.pcTag{margin-left:auto;background:#fff0d5;color:#da7800;border-radius:9px;font-size:11px;padding:5px 9px}.pcIntro{font-size:12px;color:#82867b;margin:14px 0 18px;line-height:1.8}.pcActions{display:flex;flex-wrap:wrap;gap:9px}.pcActions button{background:#f1f3ec;padding:10px 13px;font-size:12px;border-radius:10px}.pcActions button:first-child{background:#ff9200;color:#fff}.pcActions button:nth-child(2){background:#fff0d8;color:#c77300}.pcActions button:disabled{opacity:.4}.pcSpeed{display:flex;gap:12px;align-items:center;margin:19px 0;font-size:12px}.pcSpeed input{flex:1;min-width:70px;accent-color:#ff9000}.pcSpeed strong{font-size:11px}#pcStatus{font-size:12px;line-height:1.7;color:#727d73;margin:12px 0}.pcScreen{position:relative;background:#091014;border:6px solid #58615d;border-radius:17px;overflow:hidden;aspect-ratio:1.5}.pcScreen img{width:100%;height:100%;object-fit:contain;display:block}.pcScreen img:not([src]){visibility:hidden}#pcNoFrame{position:absolute;inset:0;display:grid;place-items:center;color:#93c5fd;font-size:13px}.pcExplain{display:block;color:#858d83;font-size:10px;line-height:1.7;margin:10px 0}.pcFacts{display:grid;grid-template-columns:1fr 1fr;background:#f6f7f2;border-radius:14px;padding:12px;gap:11px}.pcFacts div{display:flex;flex-direction:column;gap:5px}.pcFacts span{font-size:10px;color:#8a9188}.pcFacts b{font-size:12px}#pcErrors{font-size:10px;color:#7d8a7e;padding:12px;border:1px solid #eaede5;border-radius:12px;white-space:pre-wrap;line-height:1.7}.pcHelp{font-size:10px;line-height:1.7;color:#90968c}@media(max-width:430px){body.pcMode{padding:12px}body.pcMode #app{width:100%;height:820px}}'''
 bridge='''window.PcDebug=true;window.AndroidNav={action:(kind,payload)=>window.pcAction(kind,JSON.parse(payload))};'''
 runtime=r'''
const PC_URL='http://127.0.0.1:8790',PC_TOKEN=__TOKEN__;let pcBusy=false,pcInitialized=false,pcFrameRevision=-1,pcPollBusy=false,pcLastAppearance='',pcLastMessage='';
async function pcRequest(path,body){const response=await fetch(PC_URL+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+PC_TOKEN,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store',credentials:'omit'});const result=await response.json();if(!response.ok)throw Error(result.error||'本地服务请求失败');return result}
window.pcAction=async(kind,data={})=>{if(pcBusy){notify('上一个操作正在处理，请稍候');return}pcBusy=true;document.querySelectorAll('[data-pc]').forEach(b=>b.disabled=true);try{const result=await pcRequest('/api/action',{kind,data});notify(result.message);await pcPoll()}catch(e){notify(e.message);document.getElementById('pcStatus').textContent=e.message}finally{pcBusy=false;document.querySelectorAll('[data-pc]').forEach(b=>b.disabled=false)}};
function decodeAppearance(hex){const b=hex.match(/../g)?.map(x=>parseInt(x,16));if(!b||b.length!==12||b[0]!==1)return null;const colors=[];for(let i=4;i<12;i+=2){const rgb=b[i]|b[i+1]<<8;colors.push('#'+[Math.round((rgb>>11&31)*255/31),Math.round((rgb>>5&63)*255/63),Math.round((rgb&31)*255/31)].map(v=>v.toString(16).padStart(2,'0')).join(''))}return {theme:b[1],marker:b[2],colors}}
async function pcPoll(){if(pcPollBusy)return;pcPollBusy=true;try{const data=await pcRequest('/api/state');if(!pcInitialized){receive('map',data.mapData);routes=data.routes||[];renderRoutes();$('targetName').textContent='浪潮集团（公开示例路线）';receive('init',{gateway:'电脑 BLE 调试模式',destination:'公开示例路线'});pcInitialized=true}receive('state',data.ui||{});$('pcStatus').textContent=data.message;$('pcDot').classList.toggle('ready',data.connected);$('pcLink').textContent=data.connected?'加密 BLE · Ready':'未连接';$('pcTx').textContent=data.txSnapshots;if(!pcBusy&&document.activeElement!==$('pcSpeed')){$('pcSpeed').value=data.speed;$('pcSpeedLabel').textContent=data.speed+' km/h'};$('pcAck').textContent=data.acks;$('pcRoads').textContent=data.mapRoads?data.mapRoads+' 段真实道路':'—';$('pcSettings').textContent=data.settingsVerified?'设备回读一致':'尚未验证';$('pcFPS').textContent=data.serial?.render?data.serial.render.fps+' FPS · '+data.serial.render.averageMs+' ms/帧':'等待帧率统计';$('pcReady').textContent=data.serial?.ready===1?'READY=1':data.serial?.ready===0?'READY=0':'等待串口';$('pcBoardSpeed').textContent=data.serial?.speed!=null?data.serial.speed/10+' km/h':'—';$('pcBoardMap').textContent=data.serial?.map!=null?'ROUTE='+data.serial.route+' / MAP='+data.serial.map:'—';$('pcErrors').textContent=data.errors.length?data.errors.join('\n'):'未发现协议错误 · 模拟导航与车辆 GPS 独立';$('diagnostics').textContent='电脑演示导航位置 · 非实地导航\n车辆 GPS：'+(data.ui?.vehicle?.uart?'串口有数据':'等待串口数据')+' · 卫星 '+(data.ui?.vehicle?.satellites||0);$('serviceStatus').textContent=data.message;if(data.appearance&&data.appearance!==pcLastAppearance){const a=decodeAppearance(data.appearance);if(a){appearance=a;renderAppearance();pcLastAppearance=data.appearance}}if(data.connected&&data.frameRevision!==pcFrameRevision){const response=await fetch(PC_URL+'/api/frame',{headers:{Authorization:'Bearer '+PC_TOKEN},cache:'no-store'});if(!response.ok)throw Error('同步画面请求失败');const blob=await response.blob();if(blob.size){const url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{window.PcFrame=img;drawDevice();$('pcFrame').src=url;$('pcNoFrame').hidden=true;if(window.pcOldFrameURL)URL.revokeObjectURL(window.pcOldFrameURL);window.pcOldFrameURL=url};img.src=url;pcFrameRevision=data.frameRevision}}if(!data.connected){$('pcNoFrame').hidden=false;window.PcFrame=null;drawDevice()}drawMap()}catch(e){$('pcStatus').textContent='本地调试服务不可达：'+e.message+'。请运行 启动电脑同步调试.ps1';$('pcDot').classList.remove('ready');$('pcLink').textContent='服务不可达';if(state.connected){state.connected=false;updateState();}}finally{pcPollBusy=false}}
document.body.classList.add('pcMode');const pcBadge=document.createElement('div');pcBadge.className='previewBadge';pcBadge.textContent='电脑实机联调 · DEMO 模拟导航 · 车辆 GPS 独立';$('app').append(pcBadge);document.querySelectorAll('[data-pc]').forEach(b=>b.onclick=()=>pcAction(b.dataset.pc));$('pcSpeed').onchange=()=>pcAction('speed',{value:Number($('pcSpeed').value)});$('pcSpeed').oninput=()=>{$('pcSpeedLabel').textContent=$('pcSpeed').value+' km/h'};setInterval(pcPoll,1000);pcPoll();
'''.replace('__TOKEN__',json.dumps(token))
 html=html.replace('<link rel="stylesheet" href="style.css">','<style>'+css+extra+'</style>');html=html.replace('<script src="app.js"></script>','<script>'+bridge+'</script><script>'+js+'</script>'+panel+'<script>'+runtime+'</script>')
 preview_dir=ROOT/'output/previews'
 preview_dir.mkdir(parents=True,exist_ok=True)
 (preview_dir/'output/previews/手机应用新版界面预览.html').write_text(html,encoding='utf-8')
